  const thHexOk=v=>typeof v==="string"&&/^#[0-9a-f]{6}$/i.test(v);
  function thClean(raw){
    let obj=raw;
    if(typeof raw==="string"){try{obj=raw?JSON.parse(raw):{};}catch(e){obj={};}}
    const out={};
    if(!obj||typeof obj!=="object"||Array.isArray(obj))return out;
    for(const st of TH_STYLES){
      const t=obj[st];if(!t||typeof t!=="object")continue;
      const c={};
      for(const k of TH_COLOR_KEYS)if(thHexOk(t[k]))c[k]=t[k].toUpperCase();
      for(const k of TH_MAT_KEYS)if(TH_MATS.includes(t[k])&&t[k]!=="original")c[k]=t[k];
      if(Object.keys(c).length)out[st]=c;
    }
    return out;
  }
  const thSerialize=o=>Object.keys(o).length?JSON.stringify(o):"";
  const thRgb=h=>[1,3,5].map(i=>parseInt(h.slice(i,i+2),16));
