  shadow.getElementById('rx7-panel').parentNode.append(epPanel);
  const epGet=id=>shadow.getElementById(id);
  const epUi={
    panel:epPanel,frame:epGet('ep-frame'),rpm:epGet('ep-rpm-group'),speed:epGet('ep-speed-group'),dual:epGet('ep-dual-group'),
    rpmDial:epGet('ep-rpm-dial'),rpmNeedle:epGet('ep-rpm-needle'),speedDial:epGet('ep-speed-dial'),speedNeedle:epGet('ep-speed-needle'),
    turboNeedle:epGet('ep-turbo-needle'),nitroNeedle:epGet('ep-nitro-needle'),
    rpmScale:epGet('ep-rpm-scale'),speedScale:epGet('ep-speed-scale'),speedInner:epGet('ep-speed-inner'),turboScale:epGet('ep-turbo-scale'),nitroScale:epGet('ep-nitro-scale'),
    turboGrp:epGet('ep-turbo-grp'),nitroGrp:epGet('ep-nitro-grp'),dualFace:epGet('ep-dual-face'),
    speedUnit:epGet('ep-speed-unit'),speedUnit2:epGet('ep-speed-unit2'),gear:epGet('ep-gear'),odo:epGet('ep-odo-digits'),vtec:epGet('ep-vtec'),
    shift:epGet('ep-shift'),warnings:epGet('ep-warnings'),gcPath:epGet('ep-gc-path'),
    bezel:['ep-hs','ep-bz'].map(epGet),plate:['ep-pl','ep-pl-t','ep-pl-s','ep-pl-e'].map(epGet),knobs:[epGet('ep-knob1'),epGet('ep-knob2')],
    icons:{tyre:epGet('ep-tyre'),engine:epGet('ep-engine'),susp:epGet('ep-susp')}
  };

  // ===================== v0.9.97 Mitsubishi Evo VIII / Subaru WRX STi twin-dial cluster (panel DOM) =====================
  const RL_REACH=.30;                         // needle tip = inner end of the major tick + 30 % of its length (same rule as every other skin)
  const rlXY=(cx,cy,r,deg)=>[cx+r*Math.sin(deg*Math.PI/180),cy-r*Math.cos(deg*Math.PI/180)];
  const rlN=v=>(Math.round(v*100)/100).toString();
  const rlArc=(cx,cy,r,a0,a1)=>{const [x0,y0]=rlXY(cx,cy,r,a0),[x1,y1]=rlXY(cx,cy,r,a1);return `M${rlN(x0)} ${rlN(y0)} A${r} ${r} 0 ${Math.abs(a1-a0)>180?1:0} 1 ${rlN(x1)} ${rlN(y1)}`;};
  /* ticks + numerals (+ red band). c = {cx,cy,rOut,majLen,midLen,minLen,rNum,fs,start,sweep,majorCount,minorPer,midEvery,label,redFrom,rBand,bandW} */
  function rlDial(c){
    const total=c.majorCount*c.minorPer;let out='',nums='';
    for(let i=0;i<=total;i++){
      const f=i/total,deg=c.start+c.sweep*f,major=i%c.minorPer===0,mid=!major&&c.midEvery&&i%c.midEvery===0,red=c.redFrom!=null&&f>=c.redFrom-1e-9;
      const len=major?c.majLen:mid?c.midLen:c.minLen;
      const [x1,y1]=rlXY(c.cx,c.cy,c.rOut-len,deg),[x2,y2]=rlXY(c.cx,c.cy,c.rOut,deg);
      out+=`<line class="rl-tick${major?' maj':mid?' mid':''}${red?' red':''}" x1="${rlN(x1)}" y1="${rlN(y1)}" x2="${rlN(x2)}" y2="${rlN(y2)}"/>`;
      if(major&&c.label){
        const [tx,ty]=rlXY(c.cx,c.cy,c.rNum,deg);
        nums+=`<text class="rl-num${red?' red':''}" x="${rlN(tx)}" y="${rlN(ty)}" style="font-size:${c.fs}px">${c.label(i/c.minorPer)}</text>`;
      }
    }
    if(c.redFrom!=null)out+=`<path class="rl-redband" d="${rlArc(c.cx,c.cy,c.rBand,c.start+c.sweep*c.redFrom,c.start+c.sweep)}" stroke-width="${c.bandW}"/>`;
    return out+nums;
  }
  /* face + ring for either variant (Evo = white face + silver ring, STi = deep-blue face + gold ring) */
  const rlFace=(cx,cy,R,w)=>
    `<circle class="rl-e" cx="${cx}" cy="${cy}" r="${R-w+.5}" fill="url(#rl-face-e)"/><circle class="rl-s" cx="${cx}" cy="${cy}" r="${R-w+.5}" fill="url(#rl-face-s)"/>`+
    `<circle class="rl-e" cx="${cx}" cy="${cy}" r="${R-w/2}" fill="none" stroke="url(#rl-ring-e)" stroke-width="${w}"/><circle class="rl-s" cx="${cx}" cy="${cy}" r="${R-w/2}" fill="none" stroke="url(#rl-ring-s)" stroke-width="${w}"/>`+
    `<circle cx="${cx}" cy="${cy}" r="${R-.5}" fill="none" stroke="#000" stroke-opacity=".55" stroke-width="1"/><circle cx="${cx}" cy="${cy}" r="${R-w+.5}" fill="none" stroke="#000" stroke-opacity=".4" stroke-width="1.2"/>`;
  /* needle: Evo = sharp tapered red blade, STi = slim gold baton with a rounded tip */
  function rlNeedle(id,cx,cy,L,wB,tail,startDeg){
    const p=pts=>pts.map(q=>q[0].toFixed(2)+','+q[1].toFixed(2)).join(' ');
    const e=[[-wB,tail],[-wB*.55,-L*.4],[0,-L],[wB*.55,-L*.4],[wB,tail]];
    const gw=wB*.62,sw=gw*.8,b=gw*.6,yb=-(L-sw/2-b);
    const g=`M${(-gw).toFixed(2)} ${tail} L${(-b).toFixed(2)} ${yb.toFixed(2)} A${b.toFixed(2)} ${b.toFixed(2)} 0 0 1 ${b.toFixed(2)} ${yb.toFixed(2)} L${gw.toFixed(2)} ${tail} Z`;
    return `<g id="${id}" class="rl-needle" transform="rotate(${startDeg} ${cx} ${cy})"><g transform="translate(${cx} ${cy})">`+
      `<polygon class="rl-n-e rl-e" points="${p(e)}"/><path class="rl-n-s rl-s" d="${g}" stroke-width="${sw.toFixed(2)}"/><circle class="rl-n-s rl-s" cx="0" cy="${tail}" r="${(gw*1.45).toFixed(2)}" stroke="none"/></g></g>`;
  }
  const rlHub=(cx,cy,r)=>`<circle class="rl-hub" cx="${cx}" cy="${cy}" r="${r}"/><circle class="rl-hub-in" cx="${cx}" cy="${cy}" r="${(r*.36).toFixed(1)}"/>`;
  const RL_TACH={cx:176,cy:176,R:176,rOut:158,majLen:19,minLen:10,rNum:120,rBand:162.5,bandW:5,start:-130,sweep:260};
  const RL_SPD={cx:176,cy:176,R:176,rOut:158,majLen:18,midLen:12,minLen:8,rNum:116,start:-130,sweep:260};
  const RL_SUB={cx:94,cy:74,rOut:62,majLen:11,midLen:7,minLen:5,rNum:40,fs:14,rBand:66,bandW:3,start:-90,sweep:180};
  const rlTip=g=>(g.rOut-g.majLen)+RL_REACH*g.majLen;
  const RL_HALF='M18 74 A76 76 0 0 1 170 74 L170 99 Q170 104 165 104 L23 104 Q18 104 18 99 Z';
  const rlHalf=(id,scaleId,needleId,cap)=>
    `<svg id="${id}" class="rl-half" viewBox="0 0 188 104"><path class="rl-e" d="${RL_HALF}" fill="url(#rl-face-e)"/><path class="rl-s" d="${RL_HALF}" fill="url(#rl-face-s)"/>`+
    `<path class="rl-hring rl-e" d="${RL_HALF}" stroke="url(#rl-ring-e)"/><path class="rl-hring rl-s" d="${RL_HALF}" stroke="url(#rl-ring-s)"/>`+
    `<g id="${scaleId}"></g>${rlNeedle(needleId,94,74,rlTip(RL_SUB),2.8,7,-90)}${rlHub(94,74,8.5)}<text class="rl-scap" x="94" y="98.5">${cap}</text></svg>`;
  const rlPanel=document.createElement('div');
  rlPanel.id='rl-panel';rlPanel.className='rl-panel';
  rlPanel.setAttribute('aria-label','Mitsubishi Evo VIII / Subaru WRX STi twin-dial cluster');
