  shadow.getElementById('rx7-panel').parentNode.append(rlPanel);
  const rlGet=id=>shadow.getElementById(id);
  const rlUi={
    panel:rlPanel,frame:rlGet('rl-frame'),rpm:rlGet('rl-rpm-group'),speed:rlGet('rl-speed-group'),dual:rlGet('rl-dual-group'),
    rpmDial:rlGet('rl-rpm-dial'),rpmNeedle:rlGet('rl-rpm-needle'),speedDial:rlGet('rl-speed-dial'),speedNeedle:rlGet('rl-speed-needle'),
    turboNeedle:rlGet('rl-turbo-needle'),nitroNeedle:rlGet('rl-nitro-needle'),
    rpmScale:rlGet('rl-rpm-scale'),speedScale:rlGet('rl-speed-scale'),turboScale:rlGet('rl-turbo-scale'),nitroScale:rlGet('rl-nitro-scale'),
    turboGrp:rlGet('rl-turbo-grp'),nitroGrp:rlGet('rl-nitro-grp'),
    speedUnit:rlGet('rl-speed-unit'),gear:rlGet('rl-gear'),odo:rlGet('rl-odo-digits'),shift:rlGet('rl-shift'),warnings:rlGet('rl-warnings'),gcPath:rlGet('rl-gc-path'),
    bezel:['rl-hs','rl-bz-e','rl-bz-s'].map(rlGet),plate:['rl-pl-e','rl-pl-s','rl-pl-sh','rl-pl-ed'].map(rlGet),acc:rlGet('rl-acc'),
    icons:{tyre:rlGet('rl-tyre'),engine:rlGet('rl-engine'),susp:rlGet('rl-susp')}
  };

  // ===================== v0.9.99 Toyota Supra / Mazda RX-8 cowled-dial cluster (panel DOM) =====================
  const SX_REACH=.30;                         // needle tip = inner end of the major tick + 30 % of its length (same rule as every other skin)
  const sxXY=(cx,cy,r,deg)=>[cx+r*Math.sin(deg*Math.PI/180),cy-r*Math.cos(deg*Math.PI/180)];
  const sxN=v=>(Math.round(v*100)/100).toString();
  const sxArc=(cx,cy,r,a0,a1)=>{const [x0,y0]=sxXY(cx,cy,r,a0),[x1,y1]=sxXY(cx,cy,r,a1);return `M${sxN(x0)} ${sxN(y0)} A${r} ${r} 0 ${Math.abs(a1-a0)>180?1:0} 1 ${sxN(x1)} ${sxN(y1)}`;};
  /* ticks + numerals (+ red band). c = {cx,cy,rOut,majLen,midLen,minLen,rNum,fs,start,sweep,majorCount,minorPer,midEvery,label,redFrom,rBand,bandW} */
  function sxDial(c){
    const total=c.majorCount*c.minorPer;let out='',nums='';
    for(let i=0;i<=total;i++){
      const f=i/total,deg=c.start+c.sweep*f,major=i%c.minorPer===0,mid=!major&&c.midEvery&&i%c.midEvery===0,red=c.redFrom!=null&&f>=c.redFrom-1e-9;
      const len=major?c.majLen:mid?c.midLen:c.minLen;
      const [x1,y1]=sxXY(c.cx,c.cy,c.rOut-len,deg),[x2,y2]=sxXY(c.cx,c.cy,c.rOut,deg);
      out+=`<line class="sx-tick${major?' maj':mid?' mid':''}${red?' red':''}" x1="${sxN(x1)}" y1="${sxN(y1)}" x2="${sxN(x2)}" y2="${sxN(y2)}"/>`;
      if(major&&c.label){
        const [tx,ty]=sxXY(c.cx,c.cy,c.rNum,deg);
        nums+=`<text class="sx-num${red?' red':''}" x="${sxN(tx)}" y="${sxN(ty)}" style="font-size:${c.fs}px">${c.label(i/c.minorPer)}</text>`;
      }
    }
    if(c.redFrom!=null)out+=`<path class="sx-redband" d="${sxArc(c.cx,c.cy,c.rBand,c.start+c.sweep*c.redFrom,c.start+c.sweep)}" stroke-width="${c.bandW}"/>`;
    return out+nums;
  }
  /* deep-set dial: face + cowl shadow over the top + ring (Supra = dark titanium, RX-8 = chrome) + a dark lip just inside the ring */
  const sxFace=(cx,cy,R,w)=>
    `<circle class="sx-a" cx="${cx}" cy="${cy}" r="${R-w+.5}" fill="url(#sx-face-a)"/><circle class="sx-b" cx="${cx}" cy="${cy}" r="${R-w+.5}" fill="url(#sx-face-b)"/>`+
    `<circle cx="${cx}" cy="${cy}" r="${R-w+.5}" fill="url(#sx-cowl)"/>`+
    `<circle cx="${cx}" cy="${cy}" r="${(R-w-1.5).toFixed(1)}" fill="none" stroke="#000" stroke-opacity=".38" stroke-width="3"/>`+
    `<circle class="sx-a" cx="${cx}" cy="${cy}" r="${R-w/2}" fill="none" stroke="url(#sx-ring-a)" stroke-width="${w}"/><circle class="sx-b" cx="${cx}" cy="${cy}" r="${R-w/2}" fill="none" stroke="url(#sx-ring-b)" stroke-width="${w}"/>`+
    `<circle cx="${cx}" cy="${cy}" r="${R-.5}" fill="none" stroke="#000" stroke-opacity=".6" stroke-width="1"/><circle cx="${cx}" cy="${cy}" r="${R-w+.5}" fill="none" stroke="#000" stroke-opacity=".45" stroke-width="1.2"/>`;
  /* needle: Supra = square-ended white bar with an orange tip, RX-8 = truncated red wedge with a lit core (neither pointed nor rounded) */
  function sxNeedle(id,cx,cy,L,wB,tail,startDeg){
    const p=pts=>pts.map(q=>q[0].toFixed(2)+','+q[1].toFixed(2)).join(' ');
    const bw=wB*1.4,tipH=L*.26;
    const wedge=[[-wB*1.15,tail],[-wB*.42,-L],[wB*.42,-L],[wB*1.15,tail]];
    const core=[[-wB*.38,tail],[-wB*.14,-L*.96],[wB*.14,-L*.96],[wB*.38,tail]];
    return `<g id="${id}" class="sx-needle" transform="rotate(${startDeg} ${cx} ${cy})"><g transform="translate(${cx} ${cy})">`+
      `<rect class="sx-n-a" x="${(-bw/2).toFixed(2)}" y="${(-L).toFixed(2)}" width="${bw.toFixed(2)}" height="${(L+tail).toFixed(2)}" rx=".6"/>`+
      `<rect class="sx-n-a2" x="${(-bw/2).toFixed(2)}" y="${(-L).toFixed(2)}" width="${bw.toFixed(2)}" height="${tipH.toFixed(2)}" rx=".6"/>`+
      `<polygon class="sx-n-b" points="${p(wedge)}"/><polygon class="sx-n-b2" points="${p(core)}"/></g></g>`;
  }
  const sxHub=(cx,cy,r)=>`<circle class="sx-hub" cx="${cx}" cy="${cy}" r="${r}"/><circle class="sx-hub-in" cx="${cx}" cy="${cy}" r="${(r*.34).toFixed(1)}"/>`;
  const SX_TACH={cx:176,cy:176,R:176,rOut:158,majLen:19,minLen:10,rNum:120,rBand:162.5,bandW:5,start:-130,sweep:260};
  const SX_SPD={cx:176,cy:176,R:176,rOut:158,majLen:18,midLen:12,minLen:8,rNum:116,start:-130,sweep:260};
  const SX_SUB={cx:52,cy:52,rOut:41,majLen:7,midLen:5,minLen:3.4,rNum:26.5,fs:11,rBand:43.6,bandW:2.2,start:-135,sweep:270};
  const sxTip=g=>(g.rOut-g.majLen)+SX_REACH*g.majLen;
  const sxMini=(id,scaleId,needleId,cap)=>
    `<svg id="${id}" class="sx-mini" viewBox="0 0 104 104">${sxFace(52,52,50,5)}<g id="${scaleId}"></g>`+
    `${sxNeedle(needleId,52,52,sxTip(SX_SUB),2.6,8,-135)}${sxHub(52,52,6.5)}<text class="sx-scap" x="52" y="87">${cap}</text></svg>`;
  /* NITRO as a row of 10 blocks that fill / drain (last three are the "hot" blocks) */
  const SX_NB=10;
  const sxNitro=id=>{
    let b='';for(let i=0;i<SX_NB;i++)b+=`<rect class="sx-blk${i>=SX_NB-3?' hot':''}" x="${(22.6+i*14.6).toFixed(1)}" y="37" width="11.4" height="30" rx="2"/>`;
    return `<svg id="${id}" class="sx-nbar" viewBox="0 0 188 104"><rect class="sx-a" x="9" y="22" width="170" height="60" rx="12" fill="url(#sx-face-a)" stroke="url(#sx-ring-a)" stroke-width="3.5"/>`+
      `<rect class="sx-b" x="9" y="22" width="170" height="60" rx="12" fill="url(#sx-face-b)" stroke="url(#sx-ring-b)" stroke-width="3.5"/>${b}`+
      `<text class="sx-scap" x="94" y="99">NITRO</text><text class="sx-scap" x="22" y="99">E</text><text class="sx-scap" x="166" y="99">F</text></svg>`;
  };
  const sxPanel=document.createElement('div');
  sxPanel.id='sx-panel';sxPanel.className='sx-panel';
  sxPanel.setAttribute('aria-label','Toyota Supra / Mazda RX-8 cowled-dial cluster');
