  function civ2AuxMarks(node,cx,cy,r,start,end,steps,majorEvery,labelSet,redFrom,redTo){
    const ns='http://www.w3.org/2000/svg',frag=document.createDocumentFragment();
    for(let i=0;i<=steps;i++){
      const angle=(start+(end-start)*(i/steps))*Math.PI/180,major=i%majorEvery===0;
      const inner=r-(major?11:6),x=Math.sin(angle),y=-Math.cos(angle);
      const isRed=(redFrom!=null&&i<=redFrom)||(redTo!=null&&i>=redTo);
      const line=document.createElementNS(ns,'line');
      line.setAttribute('class','civ2-aux-tick'+(major?' major':'')+(isRed?' red':''));
      line.setAttribute('x1',(cx+x*inner).toFixed(2));line.setAttribute('y1',(cy+y*inner).toFixed(2));
      line.setAttribute('x2',(cx+x*r).toFixed(2));line.setAttribute('y2',(cy+y*r).toFixed(2));frag.append(line);
      if(labelSet?.[i]){
        const text=document.createElementNS(ns,'text');text.setAttribute('class','civ2-aux-num');
        text.setAttribute('x',(cx+x*(r-23)).toFixed(2));
        text.setAttribute('y',(cy+y*(r-23)).toFixed(2));text.setAttribute('text-anchor','middle');
        text.setAttribute('dominant-baseline','central');text.textContent=labelSet[i];frag.append(text);
      }
    }
    node.replaceChildren(frag);
  }
  // Nitro: E at lower-left, F at upper-left. Turbo: 0 to 3 on right arc.
