    if(settings.showNitro)rot(civ2Ui.nitroNeedle,nitro/NITRO_CAPACITY,230,310,102.5,116);
    if(settings.showTurbo)rot(civ2Ui.turboNeedle,turboDisplay,130,50,102.5,116);
