      impactFlash.style.background=`
        radial-gradient(ellipse at center,transparent 42%,rgba(${color},.22) 85%,rgba(${color},.65) 100%),
        linear-gradient(90deg,rgba(${color},.33),transparent 14%,transparent 86%,rgba(${color},.33))`;
