    if(!settings.impactFeedbackShake)return "shake off";
    const reduced=Boolean(window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches)&&!settings.impactFeedbackIgnoreReducedMotion;
    if(reduced)return 'shake skipped: system "reduce motion" is ON (tick "Shake even if reduce motion is ON")';
    const targets=[];
    if(settings.hudEnabled&&host.style.display!=="none"&&typeof hud.animate==="function")
      targets.push({el:hud,base:`scale(${gaugeValue("hudScale")/100})`,k:1});
